def cls(x):
    q=x['q'];a=str(x['a']);t=(q+' || '+a).lower();ql=q.lower();s=x['sec'].lower()
    if len(q.strip())<6: return 'bad'
    if has(ql,['synonym','antonym','opposite of','idiom','spelled','spelling','preposition','passive','active voice','indirect speech','direct speech','narration','plural','fill in the blank','correct sentence','one word','meaning of','means\??','verb','noun','adjective','adverb','tense','grammatically','article','proverb','pronoun','conjunction']) and not has(ql,['quran','surah','islam','hadith']): return 'eng'
    if has(ql,['series','odd one out','code language','in a certain code','blood relation','next in the','what comes next','missing (number|letter|term)']): return 'verbal'
    if has(ql,CUR) and not has(ql,['founded in','established in']): return 'cur'
    if has(t,ISL): return 'isl'
    if has(t,PAK): return 'pak'
    if re.search(r'\d',q) and has(ql,MATH): return 'math'
    if has(ql,['log','matrix','derivative','integral','equation','triangle','circle','angle','polynomial','quadratic','fraction','prime','lcm','hcf','percentage','average','probability','sin','cos','tan','radius','perimeter','area of','volume of']): return 'math'
    if has(t,SCI): return 'sci'
    if s=='english' or has(ql,ENG): return 'eng'
    if s=='islamiat': return 'isl'
    if s=='pakistan studies': return 'pak'
    if 'current' in s: return 'cur'
    if has(ql,VERB): return 'verbal'
    return 'gk'
